import { mkdtemp, writeFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
const fixture = vi.hoisted(() => ({ root: '' }));
vi.mock('./electron/utils/paths', () => ({ getOpenClawConfigDir: () => fixture.root }));
import { createTaskLedgerApi } from './electron/services/task-ledger-api';
it('requires actual owner/artifact readback rather than caller-chosen coherent digests', async () => {
  fixture.root = await mkdtemp(join(tmpdir(), 'a3-closed-owner-counterexample-'));
  try {
    const api = createTaskLedgerApi();
    const before = await api.createNode({ workspaceId: 'isolated-a3-repro', node: { title: 'Agent driven negative control', kind: 'task', owner: 'agent', status: 'review' } });
    const node = before.snapshot.nodes[0];
    const claim = { schema: 'TaskCompletionClaim/v1', taskId: node.id, candidateDigest: 'a'.repeat(64), generation: 'never-existed-session-generation', verifierDigest: 'b'.repeat(64), effectDigest: 'b'.repeat(64), priorStatus: 'review' };
    const result = await api.submitCompletion({ workspaceId: 'isolated-a3-repro', claim, idempotencyKey: 'no-real-owner-or-artifact' });
    const observed = result.snapshot.nodes.find(item => item.id === node.id);
    await writeFile('D:/tmp/autonomy-a3-r1/closed-candidate-counterexample.json', JSON.stringify({ driven_by: 'agent', actor: 'codex-a3-owner-audit', sourceCommit: '80c0fd41f',
      sessionOrRuntimeOwnerSupplied: false, artifactOrReceiptCreated: false, expectedAccepted: false, actualAccepted: result.accepted, actualTaskStatus: observed?.status,
      callerAuthored: claim, events: result.snapshot.eventsCount, requirementViolated: 'No model/caller self-proof; read actual task/candidate/generation/check/reviewer/effect owners and disk artifacts' }, null, 2));
    expect(result.accepted).toBe(false);
    expect(observed?.status).not.toBe('done');
  } finally { await rm(fixture.root, { recursive: true, force: true }); }
});
